package rework

import (
	"context"
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"github.com/kapetan-io/dispatch/internal/environment"
)

// clone is the local clone of the GitHub repo slug, an owner/name. The report fetches into it and
// otherwise only reads it with git cat-file, merge-base, diff, grep, blame and show. It never
// checks out, resets or cleans.
type clone struct {
	env    environment.Environment
	path   string
	remote string
	slug   string
	// marked caches markedGenerated by commit.
	marked map[string]map[string]bool
}

func (c *clone) git(ctx context.Context, args ...string) (string, error) {
	return c.gitWith(ctx, "", args...)
}

// gitWith runs git with stdin as its input.
func (c *clone) gitWith(ctx context.Context, stdin string, args ...string) (string, error) {
	cmd := c.env.Command(ctx, "git", append([]string{"-C", c.path, "-c", "core.quotePath=false"}, args...)...)
	cmd.Stdin = strings.NewReader(stdin)
	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("git %s in %s: %w", strings.Join(args[:min(2, len(args))], " "), c.path, err)
	}
	return string(out), nil
}

// missing is the commits of shas the clone does not hold, read with one git cat-file.
func (c *clone) missing(ctx context.Context, shas []string) []string {
	var asked []string
	for _, sha := range shas {
		if sha != "" {
			asked = append(asked, sha)
		}
	}
	if len(asked) == 0 {
		return nil
	}
	out, err := c.gitWith(ctx, strings.Join(asked, "^{commit}\n")+"^{commit}\n", "cat-file", "--batch-check")
	if err != nil {
		return asked
	}
	var gone []string
	for i, line := range strings.Split(strings.TrimSuffix(out, "\n"), "\n") {
		if i < len(asked) && strings.HasSuffix(line, " missing") {
			gone = append(gone, asked[i])
		}
	}
	return gone
}

// fetchMissing fetches each of shas the clone lacks, such as the head of a PR whose branch was
// deleted. A fetch that fails leaves what the clone already holds.
func (c *clone) fetchMissing(ctx context.Context, shas []string) {
	if gone := c.missing(ctx, shas); len(gone) > 0 {
		_, _ = c.git(ctx, append([]string{"fetch", "-q", c.remote}, gone...)...)
	}
}

// mergeBase is the commit a PR's diff starts from, empty when either commit is missing.
func (c *clone) mergeBase(ctx context.Context, base, head string) string {
	if base == "" || head == "" {
		return ""
	}
	out, err := c.git(ctx, "merge-base", base, head)
	if err != nil {
		return ""
	}
	return strings.TrimSpace(out)
}

// hunk is the lines a diff changed in the old side of a file: count lines from start, or, when
// count is 0, an insertion after line start.
type hunk struct{ start, count int }

// fileChange is one file a diff changed: its path before, its path after (empty when deleted)
// and the hunks of its old side.
type fileChange struct {
	old, new string
	hunks    []hunk
}

var hunkHeader = regexp.MustCompile(`^@@ -(\d+)(?:,(\d+))? \+\d+(?:,\d+)? @@`)

// changes is the files base...head changed that existed at base, in diff order, with renames
// followed. A file the diff adds has no old side, so it is left out.
func (c *clone) changes(ctx context.Context, base, head string) ([]fileChange, error) {
	out, err := c.git(ctx, "diff", "--no-ext-diff", "--no-color", "-U0", "-M", "--src-prefix=a/", "--dst-prefix=b/", base+"..."+head)
	if err != nil {
		return nil, err
	}
	var files []fileChange
	var old string
	current := -1
	// header is true between a file's "diff --git" line and its first hunk, the only place its
	// ---/+++ lines are, since a deleted line that starts "-- " also reads "--- ".
	header := false
	for _, line := range strings.Split(out, "\n") {
		switch {
		case strings.HasPrefix(line, "diff --git "):
			header, old, current = true, "", -1
		case header && strings.HasPrefix(line, "--- "):
			old = diffPath(line, "a/")
		case header && strings.HasPrefix(line, "+++ ") && old != "":
			files = append(files, fileChange{old: old, new: diffPath(line, "b/")})
			current = len(files) - 1
		case strings.HasPrefix(line, "@@ ") && current >= 0:
			header = false
			m := hunkHeader.FindStringSubmatch(line)
			if m == nil {
				continue
			}
			start, _ := strconv.Atoi(m[1])
			count := 1
			if m[2] != "" {
				count, _ = strconv.Atoi(m[2])
			}
			files[current].hunks = append(files[current].hunks, hunk{start, count})
		}
	}
	return files, nil
}

// diffPath is the path of a ---/+++ line without its side's prefix, empty for /dev/null. Git ends
// a path that holds a space with a tab, and C-quotes one that holds a quote, a backslash or a
// control character.
func diffPath(line, prefix string) string {
	p := strings.TrimSuffix(line[len("--- "):], "\t")
	if p == "/dev/null" {
		return ""
	}
	if strings.HasPrefix(p, `"`) {
		if unquoted, err := strconv.Unquote(p); err == nil {
			p = unquoted
		}
	}
	return strings.TrimPrefix(p, prefix)
}

// generatedMarker is the line Go's convention puts in a generated file.
const generatedMarker = `^// Code generated .* DO NOT EDIT\.$`

// markedGenerated is the Go files at commit rev that carry generatedMarker.
func (c *clone) markedGenerated(ctx context.Context, rev string) map[string]bool {
	if files, ok := c.marked[rev]; ok {
		return files
	}
	files := map[string]bool{}
	// git grep exits 1 when no file matches, so an error means none is marked.
	out, _ := c.git(ctx, "grep", "-l", "-z", "-E", generatedMarker, rev, "--", "*.go")
	for _, name := range strings.Split(out, "\x00") {
		if name, ok := strings.CutPrefix(name, rev+":"); ok {
			files[name] = true
		}
	}
	if c.marked == nil {
		c.marked = map[string]map[string]bool{}
	}
	c.marked[rev] = files
	return files
}

// counted reports whether the lines of the file at path count toward fix chains: it is not a
// test, a lockfile or generated, by its name or by its marker line in marked.
func counted(path string, marked map[string]bool) bool {
	return !testPath.MatchString(path) && !generatedPath.MatchString(path) && !marked[path]
}

// lineCounts is the lines base...head added and deleted in files whose lines count toward fix
// chains, judged by the path each file had at base.
func (c *clone) lineCounts(ctx context.Context, base, head string) (added, deleted int, err error) {
	out, err := c.git(ctx, "diff", "--no-ext-diff", "--no-color", "--numstat", "-z", "-M", base+"..."+head)
	if err != nil {
		return 0, 0, err
	}
	atBase, atHead := c.markedGenerated(ctx, base), c.markedGenerated(ctx, head)
	// -z prints "added\tdeleted\tpath" for a file, and for a rename "added\tdeleted\t" followed by
	// the old and the new path as fields of their own.
	fields := strings.Split(out, "\x00")
	for i := 0; i < len(fields); i++ {
		parts := strings.SplitN(fields[i], "\t", 3)
		if len(parts) < 3 {
			continue
		}
		old, next := parts[2], parts[2]
		if old == "" && i+2 < len(fields) {
			old, next = fields[i+1], fields[i+2]
			i += 2
		}
		if parts[0] == "-" || !counted(old, atBase) || atHead[next] {
			continue
		}
		a, _ := strconv.Atoi(parts[0])
		d, _ := strconv.Atoi(parts[1])
		added += a
		deleted += d
	}
	return added, deleted, nil
}

var blameLine = regexp.MustCompile(`^([0-9a-f]{40}) \d+ \d+`)

// blame counts, by the commit that wrote them, the lines of path at rev that hunks change.
func (c *clone) blame(ctx context.Context, rev, path string, hunks []hunk) map[string]int {
	args := []string{"blame", "--porcelain"}
	for _, h := range hunks {
		if h.count > 0 {
			args = append(args, "-L", fmt.Sprintf("%d,+%d", h.start, h.count))
		}
	}
	if len(args) == 2 {
		return nil
	}
	out, err := c.git(ctx, append(args, rev, "--", path)...)
	if err != nil {
		return nil
	}
	counts := map[string]int{}
	for _, line := range strings.Split(out, "\n") {
		if m := blameLine.FindStringSubmatch(line); m != nil {
			counts[m[1]]++
		}
	}
	return counts
}

// show is the file at path in rev, false when rev has no such file.
func (c *clone) show(ctx context.Context, rev, path string) (string, bool) {
	out, err := c.git(ctx, "show", rev+":"+path)
	return out, err == nil
}
